import{_ as i,a8 as t,o as d,c as u,ah as c,a,a3 as s,K as e,L as g}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const k=JSON.parse('{"title":"跨库去重与内容审计教训","description":"","frontmatter":{"type":"lesson","scope":"global","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-12T00:00:00.000Z","tags":["去重","审计","内容迁移","知识库","方法论"]},"headers":[],"relativePath":"vault/Memory/Lessons/跨库去重与内容审计教训.md","filePath":"vault/Memory/Lessons/跨库去重与内容审计教训.md","lastUpdated":1789374053000}'),_={name:"vault/Memory/Lessons/跨库去重与内容审计教训.md"};function m(h,o,b,p,q,f){const n=t("VPNolebaseInlineLinkPreview"),r=t("NolebaseGitContributors"),l=t("NolebaseGitChangelog");return d(),u("div",null,[o[2]||(o[2]=c('<h1 id="跨库去重与内容审计教训" tabindex="-1">跨库去重与内容审计教训 <a class="header-anchor" href="#跨库去重与内容审计教训" aria-label="Permalink to “跨库去重与内容审计教训”">​</a></h1><blockquote><p>提炼自 2026-07 知识库去重 + 2026-09 AI 资讯覆盖度审计，属可复用方法论。</p></blockquote><h2 id="跨库去重-必须内容哈希-标题归一化" tabindex="-1">跨库去重：必须内容哈希 + 标题归一化 <a class="header-anchor" href="#跨库去重-必须内容哈希-标题归一化" aria-label="Permalink to “跨库去重：必须内容哈希 + 标题归一化”">​</a></h2><ul><li><strong>反例（踩坑）</strong>：按 basename 去重会漏判——主库用「主题-子题.md」横线命名，迁移备份用「主题/子题.md」子目录命名，basename 不同被判&quot;唯一&quot;搬入，实际内容一致。一次清出 37 篇重复。</li><li><strong>正解</strong>：跨库去重用 <strong>md5(去空白小写正文) + 标题归一化</strong> 双重比对，不能只看文件名。近重复要用<strong>句子级</strong>而非段落级比对，避免把同笔记措辞差异当独有内容并入。</li><li><strong>导航页冗余判功能而非正文相似度</strong>：<code>机器学习基础.md</code> 串的 7 知识点 100% 已在 <code>机器学习-MOC.md</code>（后者涵盖 20+ 条），前者是后者功能性子集。difflib 全文比率对&quot;同主题不同措辞/子集&quot;不高，会误判&quot;无重复&quot;。判断导航页冗余应以<strong>知识范围是否被包含 + 导航目的是否相同</strong>为准。</li></ul><h2 id="ai-资讯覆盖度审计-二次复验-文本归一化" tabindex="-1">AI 资讯覆盖度审计：二次复验 + 文本归一化 <a class="header-anchor" href="#ai-资讯覆盖度审计-二次复验-文本归一化" aria-label="Permalink to “AI 资讯覆盖度审计：二次复验 + 文本归一化”">​</a></h2><ul><li><strong>覆盖度审计不能只看字符串匹配率</strong>：首轮自动化比对报 48 项缺失，二次关键词复验发现绝大多数是<strong>假阳性</strong>（主题已覆盖、只是措辞不同，如&quot;周报不再是流水账&quot;= 周报模板 + 文档生成）。<strong>做覆盖度审计必须二次复验。</strong></li><li><strong>PDF 抽取文本含 CJK 兼容区字符</strong>（⼯/⾃/⻚ 等，PDF 提取导致）→ 直接关键词搜索会漏匹配。<strong>必须 <code>unicodedata.normalize(&quot;NFKC&quot;, text)</code> 归一化后再检索</strong>，否则出现假阴性。</li><li><strong>校验脚本陷阱</strong>：① 自建 slug 函数易假阳性（未处理标点/大小写误报锚点失效），应用「去标点→小写→空格转连字符」；② 校验图片不能只对&quot;图注编号&quot;计数，必须<strong>逐一核对 嵌入文件名 ↔ 磁盘文件 ↔ 图注 三者一致</strong>，&quot;编号数 &lt; 图片数&quot;即存在无图注/被替换的图；③ 每轮校验必须含<strong>转义检查</strong>（<code>!\\\\[\\\\[</code> 计数），转义图片会命中 <code>![[</code> 正则造成&quot;正常&quot;假象（已两次踩坑）。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to “关联”">​</a></h2>',7)),a("ul",null,[a("li",null,[o[1]||(o[1]=s("日更流水线见 ",-1)),e(n,{href:"/knowledge/vault/Memory/Workflows/ai-hot-article-daily流水线.html"},{default:g(()=>[...o[0]||(o[0]=[s("ai-hot-article-daily流水线",-1)])]),_:1})])]),e(r),e(l)])}const C=i(_,[["render",m]]);export{k as __pageData,C as default};
